import { getGpxDataSequencesFromStrings } from '@helpers/gpxDecode.helper';

import { IHikingGpxDTO } from '../@types/DTO/hiking.dto.types';
import { IHikingGpx, IHikingGpxPoint, IHikingGpxWithWorkout } from '../@types/hiking.types';

export const mapHikingGpxToFront = (backData: IHikingGpxDTO): IHikingGpx => {
  const sequences = getGpxDataSequencesFromStrings(backData);
  const track: IHikingGpxPoint[] = sequences.latitudes!.map((lat, index) => {
    return {
      date: new Date(sequences.timestamps![index]),
      point: [lat, sequences.longitudes![index], sequences.altitudes?.[index]].filter(
        Number.isFinite,
      ) as IHikingGpxPoint['point'],
      hr: sequences.heartRates?.[index] ?? undefined,
      temp: sequences.temperatures?.[index] ?? undefined,
      cadence: sequences.cadences?.[index] ?? undefined,
    };
  });

  return {
    id: +backData.id,
    name: backData.name,
    id_hiking_schedule: backData.id_hiking_schedule ? +backData.id_hiking_schedule : null,
    dateCreate: new Date(backData.date_create),
    dateUpload: new Date(backData.date_upload),
    dateUpdate: backData.date_update ? new Date(backData.date_update) : null,
    start: new Date(backData.date_start),
    finish: new Date(backData.date_finish),
    bounds: JSON.parse(backData.bounds),
    distance: +backData.distance,
    track,

    author: {
      id: +backData.id_user,
      name: backData.user_name,
      surname: backData.user_surname,
      photo: backData.user_photo,
    },
    user: {
      id: +backData.id_user,
      name: backData.user_name,
      surname: backData.user_surname,
      photo: backData.user_photo,
    },
    activityType: backData.activity_type,

    altitude: {
      min: +backData.alt_min,
      max: +backData.alt_max,
      avg: +backData.alt_avg,
      ascent: +backData.alt_ascent,
      descent: +backData.alt_descent,
    },

    speed: {
      min: +backData.speed_min,
      max: +backData.speed_max,
      avg: +backData.speed_avg,
    },

    heartRate: backData.hr_min
      ? {
          min: +backData.hr_min,
          max: +backData.hr_max!,
          avg: +backData.hr_avg!,
        }
      : undefined,

    temperature: backData.temp_min
      ? {
          min: +backData.temp_min,
          max: +backData.temp_max!,
          avg: +backData.temp_avg!,
        }
      : undefined,

    timeMoving: +backData.time_mooving,
    timePause: +backData.time_pause,

    id_workout_track: +backData.id_workout_track,

    schedule: backData.id_hiking_schedule
      ? {
          id: +backData.id_hiking_schedule,
          name: backData.schedule_name,
          description: backData.schedule_description,
          link: backData.schedule_link || null,

          start: new Date(backData.schedule_d1),
          finish: new Date(backData.schedule_d2),

          cost: null,

          foodAct: undefined,

          routeObject: {
            id: +backData.schedule_id_route_object,
            name: backData.schedule_name,
            description: backData.schedule_description,
            is_in_distance: true,
          },

          is_self_sufficiency: false,

          article: null,
          currency: null,
        }
      : null,
  };
};

export const mapHikingGpxWithWorkoutToFront = (backData: IHikingGpxDTO): IHikingGpxWithWorkout => {
  return {
    ...mapHikingGpxToFront(backData),
    workout: backData.workout
      ? {
          id: +backData.workout?.id,

          date_start: new Date(backData.workout.date_start),
          date_finish: new Date(backData.workout.date_finish),
          distance: +backData.workout.distance,
          name: backData.workout.name,
          type: { id: +backData.workout.type_id, name: backData.workout.type_name },
        }
      : {
          id: 0,
          date_start: new Date(),
          date_finish: new Date(),
          distance: 0,
          name: '',
          type: { id: 0, name: '' },
        },
  };
};
